#!/usr/bin/env sh
# Starts one local observer session. The bridge, dedicated server, and graphical client share
# the world below; Ctrl-C stops all three.
set -eu

root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
repo=$(CDPATH= cd -- "$root/../.." && pwd)
world=${1:-"$root/.observe-world"}
# The room is installed only when mapblocks emerge.  Reuse would retain nodes and param1
# lighting generated by an older mod version, so this viewer always starts from a fresh
# disposable world.
rm -rf "$world"
mkdir -p "$world"
# OBSERVE_WORLD=open (default): the founder lives in an endless Minetest Game world generated by
# Luanti's v7 map generator from a fixed seed. OBSERVE_WORLD=room: the small experimental arena.
world_kind=${OBSERVE_WORLD:-open}
mtg_games=${MINETEST_GAME_GAMES:-/var/lib/minetest/.minetest/games}
game_path="$root/games"
gameid=ai_village
if [ "$world_kind" = open ]; then
  gameid=minetest
  [ -d "$mtg_games/minetest_game" ] || {
    echo "Minetest Game not found in $mtg_games; set MINETEST_GAME_GAMES or OBSERVE_WORLD=room" >&2
    exit 1
  }
  game_path="$root/games:$mtg_games"
  cat >"$world/world.mt" <<'EOF'
gameid = minetest
backend = sqlite3
EOF
  # The founder's mod joins the Minetest Game world as a world mod.
  mkdir -p "$world/worldmods"
  ln -s "$root/games/ai_village/mods/ai_bridge" "$world/worldmods/ai_bridge"
  cat >"$world/minetest.conf" <<'EOF'
mg_name = v7
fixed_map_seed = 424242
max_forceloaded_blocks = 64
ai_bridge_world = open
EOF
else
  cat >"$world/world.mt" <<'EOF'
gameid = ai_village
backend = sqlite3
seed = 424242
time_speed = 0
EOF
  printf 'mg_name = singlenode\n' >"$world/minetest.conf"
fi
cat >>"$world/minetest.conf" <<'EOF'
dedicated_server_step = 0.1
time_speed = 0
port = 30000
secure.http_mods = ai_bridge
enable_damage = false
creative_mode = false
default_privs =
ai_bridge_mode = observe
ai_bridge_observer = observer
EOF
# Watching speed: seconds per founder decision (experiments use 0.1).
printf 'ai_bridge_step_seconds = %s\n' "${OBSERVE_STEP_SECONDS:-0.25}" >>"$world/minetest.conf"

bridge_log="$world/bridge.log"
trace_log="$world/bridge-trace.ndjson"
server_log="$world/server.log"
SIM_LUANTI_MODE=affordance SIM_LUANTI_TRACE="$trace_log" \
  cargo run --quiet -p sim-luanti --manifest-path "$repo/Cargo.toml" >"$bridge_log" 2>&1 &
bridge_pid=$!
server_bin=$(command -v luantiserver || command -v minetestserver)
client_bin=$(command -v luanti || command -v minetest)
cleanup() {
  kill "${server_pid:-}" "$bridge_pid" 2>/dev/null || true
  wait "${server_pid:-}" "$bridge_pid" 2>/dev/null || true
}
trap cleanup EXIT INT TERM
ready=0
for _ in $(seq 1 120); do
  if grep -q 'sim-luanti listening' "$bridge_log"; then ready=1; break; fi
  if ! kill -0 "$bridge_pid" 2>/dev/null; then cat "$bridge_log" >&2; exit 1; fi
  sleep 0.25
done
[ "$ready" -eq 1 ] || { cat "$bridge_log" >&2; exit 1; }
LUANTI_GAME_PATH="$game_path" "$server_bin" --gameid "$gameid" --world "$world" \
  --config "$world/minetest.conf" >"$server_log" 2>&1 &
server_pid=$!
sleep 1
if ! kill -0 "$server_pid" 2>/dev/null; then
  cat "$server_log" >&2
  exit 1
fi
printf '%s\n' "Observer client: 127.0.0.1:30000 (world: $world)"
"$client_bin" --go --address 127.0.0.1 --port 30000 --name observer
